"""The Kimulator: a tracing interpreter over the semantic rules.

:class:`Kimulator` is the user-facing entry point of the semantic layer.  It ties
the pieces together - symbol analysis, type analysis, attribute resolution,
register state and the rule engine - and, unlike the plain simulator in
:mod:`src.circt.simulator`, it *records why* each value came out the way it did::

    >>> from mlir.parser import parse_file
    >>> import circt                      # registers hw / comb / seq
    >>> from k_circt import Kimulator
    >>> kim = Kimulator(parse_file("inputs/alu.mlir"), "ALU")
    >>> kim.evaluate({"a": 5, "b": 3, "op": 0})["result"]
    8
    >>> kim.trace_length                  # combinational probes do not tick
    0

Every clock cycle appends one :class:`TraceEntry` holding the inputs, the
register state before the edge, the settled outputs and the ordered list of
:class:`~src.k_circt.semantics.RuleApplication` records that produced them.  So
``len(kim.run(200))`` is 200, and ``kim.trace.total_steps`` is how many rules
fired to get there.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterator, List, Optional, Sequence, Union

from mlir.ir import ModuleOp, Operation

from .attributes import AttributeResolver
from .configuration import KConfiguration
from .semantics import (
    CIRCUIT_RULES,
    RuleApplication,
    RuleEngine,
    RuleSet,
    SemanticError,
)
from .state import CycleResult, MODULE_OPS, StatefulCircuit, execute_function
from .symbols import SymbolResolver
from .types import TypeResolver

__all__ = [
    "TraceEntry",
    "KTrace",
    "Kimulator",
    "find_hw_module",
    "kimulate",
]


# ---------------------------------------------------------------------------
# Trace records
# ---------------------------------------------------------------------------


@dataclass
class TraceEntry:
    """One clock cycle, plus the rules that fired during it."""

    cycle: int
    inputs: Dict[str, int] = field(default_factory=dict)
    outputs: Dict[str, int] = field(default_factory=dict)
    state: Dict[str, int] = field(default_factory=dict)
    next_state: Dict[str, int] = field(default_factory=dict)
    applications: List[RuleApplication] = field(default_factory=list)
    configuration: Optional[KConfiguration] = None

    @classmethod
    def from_cycle(
        cls, result: CycleResult, configuration: Optional[KConfiguration] = None
    ) -> "TraceEntry":
        return cls(
            cycle=result.cycle,
            inputs=dict(result.inputs),
            outputs=dict(result.outputs),
            state=dict(result.registers),
            next_state=dict(result.next_registers),
            applications=list(result.applications),
            configuration=configuration,
        )

    # -- queries ----------------------------------------------------------
    @property
    def num_steps(self) -> int:
        return len(self.applications)

    def rule_names(self) -> List[str]:
        return [application.rule for application in self.applications]

    def applications_of(self, rule: str) -> List[RuleApplication]:
        return [a for a in self.applications if a.rule == rule]

    def value(self, name: str, default: int = 0) -> int:
        for source in (self.outputs, self.state, self.inputs):
            if name in source:
                return source[name]
        return default

    def to_text(self, verbose: bool = False) -> str:
        parts = [f"cycle {self.cycle}"]
        for label, values in (
            ("in", self.inputs),
            ("state", self.state),
            ("out", self.outputs),
        ):
            if values:
                rendered = ", ".join(f"{k}={v}" for k, v in sorted(values.items()))
                parts.append(f"{label}({rendered})")
        header = " ".join(parts) + f" [{self.num_steps} rules]"
        if not verbose:
            return header
        lines = [header]
        lines.extend("    " + str(a) for a in self.applications)
        return "\n".join(lines)

    def __str__(self) -> str:
        return self.to_text()


class KTrace:
    """The sequence of cycles a :class:`Kimulator` executed."""

    def __init__(self, signals: Optional[Sequence[str]] = None) -> None:
        self.entries: List[TraceEntry] = []
        self.signals: List[str] = list(signals or ())

    # -- building ---------------------------------------------------------
    def append(self, entry: TraceEntry) -> TraceEntry:
        self.entries.append(entry)
        return entry

    def clear(self) -> None:
        self.entries.clear()

    # -- size -------------------------------------------------------------
    @property
    def length(self) -> int:
        return len(self.entries)

    def __len__(self) -> int:
        return len(self.entries)

    def __iter__(self) -> Iterator[TraceEntry]:
        return iter(self.entries)

    def __getitem__(self, index: int) -> TraceEntry:
        return self.entries[index]

    @property
    def total_steps(self) -> int:
        """How many rules fired across the whole trace."""
        return sum(entry.num_steps for entry in self.entries)

    # -- queries ----------------------------------------------------------
    @property
    def first(self) -> Optional[TraceEntry]:
        return self.entries[0] if self.entries else None

    @property
    def last(self) -> Optional[TraceEntry]:
        return self.entries[-1] if self.entries else None

    def at(self, cycle: int) -> Optional[TraceEntry]:
        for entry in self.entries:
            if entry.cycle == cycle:
                return entry
        return None

    def signal(self, name: str) -> List[int]:
        """One signal's value across every recorded cycle."""
        return [entry.value(name) for entry in self.entries]

    def outputs(self, name: Optional[str] = None) -> List[int]:
        series: List[int] = []
        for entry in self.entries:
            if name is None:
                series.append(next(iter(entry.outputs.values()), 0))
            else:
                series.append(entry.outputs.get(name, 0))
        return series

    def states(self, name: str) -> List[int]:
        return [entry.state.get(name, 0) for entry in self.entries]

    def applications(self) -> List[RuleApplication]:
        return [a for entry in self.entries for a in entry.applications]

    def rule_histogram(self) -> Dict[str, int]:
        """How many times each rule fired, useful for spotting dead rules."""
        histogram: Dict[str, int] = {}
        for application in self.applications():
            histogram[application.rule] = histogram.get(application.rule, 0) + 1
        return dict(sorted(histogram.items()))

    def to_text(self, verbose: bool = False) -> str:
        return "\n".join(entry.to_text(verbose) for entry in self.entries)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<KTrace cycles={len(self.entries)} steps={self.total_steps}>"


# ---------------------------------------------------------------------------
# Module lookup
# ---------------------------------------------------------------------------


def find_hw_module(root: Operation, name: Optional[str] = None) -> Operation:
    """Find a hardware module under ``root`` by symbol name.

    Accepts a module operation directly, so callers can pass either the parsed
    file or the ``hw.module`` they already located.
    """
    if root.name in MODULE_OPS:
        return root
    found: List[Operation] = []

    def visit(op: Operation) -> None:
        if op.name in MODULE_OPS:
            found.append(op)

    root.walk(visit)
    if not found:
        raise SemanticError("no hardware module operation found")
    if name is None:
        return found[0]
    wanted = name.lstrip("@")
    for candidate in found:
        symbol = candidate.attributes.get("sym_name")
        if symbol is not None and symbol.value == wanted:
            return candidate
    raise SemanticError(f"no hardware module named @{wanted}")


# ---------------------------------------------------------------------------
# Kimulator
# ---------------------------------------------------------------------------


class Kimulator:
    """Evaluates a circuit through explicit semantic rules, recording a trace.

    A root without any hardware module - the ``arith`` sample, say - is still
    accepted: the three analyses and :meth:`execute_function` work, and only the
    clock-driven methods report that there is nothing to simulate.
    """

    def __init__(
        self,
        root: Operation,
        module_name: Optional[str] = None,
        rules: Optional[RuleSet] = None,
        record_configurations: bool = False,
    ) -> None:
        self.root = root
        self.rules = rules if rules is not None else CIRCUIT_RULES
        self.record_configurations = record_configurations

        self.module: Optional[Operation]
        try:
            self.module = find_hw_module(root, module_name)
        except SemanticError:
            # Naming a module that is not there is a caller error; a root with no
            # hardware at all is a legitimate "analysis only" use.
            if module_name is not None:
                raise
            self.module = None

        self.circuit: Optional[StatefulCircuit] = (
            StatefulCircuit(self.module, self.rules) if self.module is not None else None
        )
        signals = (
            self.circuit.input_names + self.circuit.output_names
            if self.circuit is not None
            else []
        )
        self.trace = KTrace(signals)

        # The three analyses run over the whole parsed root, not just the module
        # being simulated, so ``kim.symbols`` answers questions about the file.
        self._symbol_resolver = SymbolResolver(root)
        self._type_resolver = TypeResolver(root, self._symbol_resolver.resolve())
        self._attribute_resolver = AttributeResolver(
            root, self._symbol_resolver.resolve()
        )

    # -- the circuit under simulation -------------------------------------
    def _require_circuit(self) -> StatefulCircuit:
        if self.circuit is None:
            raise SemanticError(
                "this Kimulator has no hardware module to simulate; use "
                "execute_function() or the symbol/type/attribute analyses"
            )
        return self.circuit

    # -- analyses ---------------------------------------------------------
    @property
    def symbols(self) -> Any:
        """The :class:`~src.k_circt.symbols.SymbolResolution` for the root."""
        return self._symbol_resolver.resolve()

    @property
    def types(self) -> Any:
        """The :class:`~src.k_circt.types.TypeResolution` for the root."""
        return self._type_resolver.resolve()

    @property
    def attributes(self) -> Any:
        """The :class:`~src.k_circt.attributes.AttributeResolution` for the root."""
        return self._attribute_resolver.resolve_all()

    @property
    def symbol_resolver(self) -> SymbolResolver:
        return self._symbol_resolver

    @property
    def type_resolver(self) -> TypeResolver:
        return self._type_resolver

    @property
    def attribute_resolver(self) -> AttributeResolver:
        return self._attribute_resolver

    # -- structure --------------------------------------------------------
    @property
    def module_name(self) -> str:
        if self.module is None:
            return ""
        symbol = self.module.attributes.get("sym_name")
        return str(symbol.value) if symbol is not None else ""

    @property
    def config(self) -> KConfiguration:
        return self._require_circuit().config

    @property
    def state(self) -> Dict[str, int]:
        return self._require_circuit().register_values()

    @property
    def input_names(self) -> List[str]:
        return self.circuit.input_names if self.circuit is not None else []

    @property
    def output_names(self) -> List[str]:
        return self.circuit.output_names if self.circuit is not None else []

    @property
    def is_sequential(self) -> bool:
        return self.circuit is not None and self.circuit.is_sequential

    @property
    def cycle(self) -> int:
        return self.circuit.cycle if self.circuit is not None else 0

    # -- lifecycle --------------------------------------------------------
    def reset(self) -> "Kimulator":
        """Assert reset and discard the recorded trace."""
        if self.circuit is not None:
            self.circuit.reset()
        self.trace.clear()
        return self

    # -- evaluation -------------------------------------------------------
    def evaluate(self, inputs: Optional[Dict[str, int]] = None) -> Dict[str, int]:
        """Settle the combinational logic; no clock edge, so no trace entry."""
        return self._require_circuit().evaluate(inputs)

    def step(self, inputs: Optional[Dict[str, int]] = None) -> TraceEntry:
        """Advance one clock cycle and record it."""
        result = self._require_circuit().step(inputs)
        snapshot = self.config.snapshot() if self.record_configurations else None
        return self.trace.append(TraceEntry.from_cycle(result, snapshot))

    def run(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        stimulus: Optional[Sequence[Dict[str, int]]] = None,
    ) -> KTrace:
        """Run ``cycles`` clock cycles, appending one trace entry per cycle."""
        self._require_circuit().set_inputs(inputs)
        for index in range(max(0, cycles)):
            override = None
            if stimulus is not None and index < len(stimulus):
                override = stimulus[index]
            self.step(override)
        return self.trace

    # -- reading results --------------------------------------------------
    def output(self, name: Optional[str] = None, default: int = 0) -> int:
        return self._require_circuit().output(name, default)

    def output_after(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        name: Optional[str] = None,
    ) -> int:
        """Run ``cycles`` cycles, settle once more, then read an output."""
        self.run(cycles, inputs)
        self._require_circuit().settle()
        return self.output(name)

    @property
    def trace_length(self) -> int:
        return self.trace.length

    @property
    def total_steps(self) -> int:
        return self.trace.total_steps

    def signal(self, name: str) -> List[int]:
        return self.trace.signal(name)

    # -- functional evaluation --------------------------------------------
    def execute_function(
        self, symbol: str, arguments: Optional[Sequence[int]] = None
    ) -> Dict[str, int]:
        """Evaluate a ``func.func`` in the same file through the ``arith`` rules."""
        func = self.symbols.operation(symbol)
        if func is None:
            raise SemanticError(f"no symbol named @{symbol.lstrip('@')}")
        return execute_function(func, arguments, self.rules)

    # -- reporting --------------------------------------------------------
    def describe_rules(self) -> str:
        return self.rules.to_text()

    def to_text(self, verbose: bool = False) -> str:
        return self.trace.to_text(verbose)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return (
            f"<Kimulator @{self.module_name} rules={len(self.rules)} "
            f"cycle={self.cycle} trace={self.trace_length}>"
        )


def kimulate(
    root: Operation,
    module_name: Optional[str] = None,
    cycles: int = 0,
    inputs: Optional[Dict[str, int]] = None,
    rules: Optional[RuleSet] = None,
) -> Kimulator:
    """Build a :class:`Kimulator` and optionally run it straight away."""
    kim = Kimulator(root, module_name, rules)
    if cycles > 0:
        kim.run(cycles, inputs)
    elif inputs is not None:
        kim.evaluate(inputs)
    return kim

"""Cycle-accurate simulator for ``hw``/``comb``/``seq`` circuits.

The simulator walks the IR produced by :mod:`src.mlir.parser`, so the circuits in
``inputs/alu.mlir`` and ``inputs/counter.mlir`` are simulated directly from their
textual form.

Each cycle runs in two phases, which is what makes the result cycle-accurate:

1. **Combinational settle** - every ``comb``/``hw`` operation is evaluated in
   data-dependency order, treating register outputs and input ports as roots.
   Because a hardware body is a graph region, the order is discovered with a
   worklist rather than assumed from the textual order.
2. **Sequential commit** - every register's next value is computed from the
   settled values, and only then are they all written.  Registers therefore all
   sample the same pre-edge state, so ``%reg`` feeding ``comb.add`` feeding
   ``%reg`` counts by one per cycle instead of racing.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple, Union

from mlir.ir import (
    Block,
    BlockArgument,
    ModuleOp,
    Operation,
    OpResult,
    Value,
    Trait,
)
from .hw_dialect import (
    ConstantOp,
    Direction,
    HWModuleOp,
    OutputOp,
    Port,
    WireOp,
    bit_width_of,
)
from .seq_dialect import SeqOp

__all__ = [
    "SimulationError",
    "CycleRecord",
    "SimulationTrace",
    "CircuitSimulator",
    "find_module",
    "list_modules",
    "simulate_combinational",
]


class SimulationError(Exception):
    """Raised when a circuit cannot be simulated."""


# ---------------------------------------------------------------------------
# Module lookup helpers
# ---------------------------------------------------------------------------


def list_modules(root: Operation) -> List[Operation]:
    """Every ``hw.module`` reachable from ``root``, in textual order."""
    found: List[Operation] = []

    def visit(op: Operation) -> None:
        if op.name in ("hw.module", "hw.module.extern"):
            found.append(op)

    root.walk(visit)
    return found


def find_module(root: Operation, name: Optional[str] = None) -> Operation:
    """Find a ``hw.module`` by symbol name (or the first one if omitted)."""
    modules = list_modules(root)
    if not modules:
        raise SimulationError("no 'hw.module' operation found")
    if name is None:
        return modules[0]
    wanted = name.lstrip("@")
    for module in modules:
        symbol = module.attributes.get("sym_name")
        if symbol is not None and symbol.value == wanted:
            return module
    raise SimulationError(f"no 'hw.module' named @{wanted}")


# ---------------------------------------------------------------------------
# Trace records
# ---------------------------------------------------------------------------


@dataclass
class CycleRecord:
    """One simulated clock cycle."""

    cycle: int
    inputs: Dict[str, int] = field(default_factory=dict)
    outputs: Dict[str, int] = field(default_factory=dict)
    registers: Dict[str, int] = field(default_factory=dict)
    next_registers: Dict[str, int] = field(default_factory=dict)

    def __str__(self) -> str:
        parts = [f"cycle={self.cycle}"]
        for label, values in (
            ("in", self.inputs),
            ("reg", self.registers),
            ("out", self.outputs),
        ):
            if values:
                rendered = ", ".join(f"{k}={v}" for k, v in sorted(values.items()))
                parts.append(f"{label}({rendered})")
        return " ".join(parts)


class SimulationTrace:
    """The waveform recorded by a simulator run."""

    def __init__(self, signal_names: Optional[Sequence[str]] = None) -> None:
        self.records: List[CycleRecord] = []
        self.signal_names: List[str] = list(signal_names or ())

    def append(self, record: CycleRecord) -> CycleRecord:
        self.records.append(record)
        return record

    @property
    def length(self) -> int:
        return len(self.records)

    def __len__(self) -> int:
        return len(self.records)

    def __iter__(self):
        return iter(self.records)

    def __getitem__(self, index: int) -> CycleRecord:
        return self.records[index]

    def signal(self, name: str) -> List[int]:
        """The value of one signal across every recorded cycle."""
        series: List[int] = []
        for record in self.records:
            for source in (record.outputs, record.registers, record.inputs):
                if name in source:
                    series.append(source[name])
                    break
            else:
                series.append(0)
        return series

    def to_text(self) -> str:
        return "\n".join(str(record) for record in self.records)


# ---------------------------------------------------------------------------
# Simulator
# ---------------------------------------------------------------------------


class CircuitSimulator:
    """Evaluates an ``hw.module`` cycle by cycle."""

    def __init__(
        self,
        module: Operation,
        record_trace: bool = True,
    ) -> None:
        if module.name not in ("hw.module", "hw.module.extern"):
            raise SimulationError(
                f"expected an 'hw.module' operation, got '{module.name}'"
            )
        self.module = module
        self.record_trace = record_trace
        self.cycle = 0
        self.trace = SimulationTrace()

        self._block: Optional[Block] = (
            module.regions[0].blocks[0]
            if module.regions and module.regions[0].blocks
            else None
        )
        self._ports: List[Port] = list(getattr(module, "ports", []) or [])
        self._input_ports = [p for p in self._ports if not p.is_output]
        self._output_ports = [p for p in self._ports if p.is_output]
        self._registers: List[Operation] = [
            op for op in self._body_ops() if isinstance(op, SeqOp)
        ]
        self._combinational: List[Operation] = [
            op
            for op in self._body_ops()
            if not isinstance(op, SeqOp) and op.num_results and not op.is_terminator
        ]
        self._output_op: Optional[Operation] = next(
            (op for op in reversed(self._body_ops()) if op.name == "hw.output"), None
        )

        self.inputs: Dict[str, int] = {p.name: 0 for p in self._input_ports}
        self.values: Dict[Any, int] = {}
        self.reset_state()

    # -- structure --------------------------------------------------------
    def _body_ops(self) -> List[Operation]:
        if self._block is None:
            return []
        return list(self._block.operations)

    @property
    def ports(self) -> List[Port]:
        return list(self._ports)

    @property
    def input_names(self) -> List[str]:
        return [p.name for p in self._input_ports]

    @property
    def output_names(self) -> List[str]:
        return [p.name for p in self._output_ports]

    @property
    def registers(self) -> List[Operation]:
        return list(self._registers)

    @property
    def is_sequential(self) -> bool:
        return bool(self._registers)

    def register_name(self, register: Operation) -> str:
        name = getattr(register, "reg_name", "") or getattr(register, "result_name", "")
        if name:
            return name
        if register.num_results and register.result(0).name:
            return register.result(0).name
        return f"reg{id(register) & 0xFFFF}"

    # -- state ------------------------------------------------------------
    def reset_state(self) -> None:
        """Assert reset: every register returns to its reset value."""
        self.cycle = 0
        self.trace = SimulationTrace(self.input_names + self.output_names)
        for register in self._registers:
            env = self._port_environment()
            reset = getattr(register, "reset_state", None)
            if callable(reset):
                try:
                    reset(env)
                except TypeError:
                    reset()
            else:  # pragma: no cover - defensive
                register.current_value = 0
        self.values = {}

    reset = reset_state

    def register_values(self) -> Dict[str, int]:
        return {
            self.register_name(register): register.get_value()
            for register in self._registers
        }

    # -- inputs -----------------------------------------------------------
    def set_input(self, name: str, value: int) -> None:
        if name not in self.inputs:
            raise SimulationError(f"'{name}' is not an input port of this module")
        self.inputs[name] = int(value)

    def set_inputs(self, values: Optional[Dict[str, int]]) -> None:
        for name, value in (values or {}).items():
            self.set_input(name, value)

    def _port_environment(self) -> Dict[Any, int]:
        env: Dict[Any, int] = {}
        if self._block is None:
            return env
        for index, argument in enumerate(self._block.arguments):
            port_name = (
                self._input_ports[index].name
                if index < len(self._input_ports)
                else argument.name
            )
            value = int(self.inputs.get(port_name, 0))
            env[argument] = value
            if port_name:
                env[port_name] = value
        return env

    # -- combinational phase ----------------------------------------------
    def settle(self) -> Dict[Any, int]:
        """Phase 1: evaluate the combinational cone to a fixed point."""
        env = self._port_environment()

        # Register outputs are roots: they hold this cycle's state.
        for register in self._registers:
            value = register.get_value()
            for result in register.results:
                env[result] = value
            name = self.register_name(register)
            if name:
                env.setdefault(name, value)

        pending = list(self._combinational)
        progress = True
        while pending and progress:
            progress = False
            deferred: List[Operation] = []
            for op in pending:
                if not self._operands_ready(op, env):
                    deferred.append(op)
                    continue
                self._evaluate_into(op, env)
                progress = True
            pending = deferred

        if pending:
            names = ", ".join(sorted({op.name for op in pending}))
            raise SimulationError(
                f"combinational loop or unsupported operation(s): {names}"
            )

        self.values = env
        return env

    def _operands_ready(self, op: Operation, env: Dict[Any, int]) -> bool:
        for operand in op.operands:
            if isinstance(operand, Value):
                if operand not in env:
                    return False
            elif operand not in env:
                return False
        return True

    def _evaluate_into(self, op: Operation, env: Dict[Any, int]) -> None:
        evaluate = getattr(op, "evaluate", None)
        if not callable(evaluate):
            raise SimulationError(f"operation '{op.name}' cannot be simulated")
        result = evaluate(env)
        if isinstance(result, (list, tuple)):
            for value, produced in zip(result, op.results):
                env[produced] = int(value)
        else:
            for produced in op.results:
                env[produced] = int(result)
                if produced.name:
                    env.setdefault(produced.name, int(result))

    # -- outputs ----------------------------------------------------------
    def read_outputs(self, env: Optional[Dict[Any, int]] = None) -> Dict[str, int]:
        env = env if env is not None else self.values
        outputs: Dict[str, int] = {}
        if self._output_op is None:
            return outputs
        for index, operand in enumerate(self._output_op.operands):
            name = (
                self._output_ports[index].name
                if index < len(self._output_ports)
                else f"out{index}"
            )
            if isinstance(operand, Value):
                outputs[name] = int(env.get(operand, 0))
            else:
                outputs[name] = int(env.get(operand, 0))
        return outputs

    def get_output(self, name: Optional[str] = None) -> int:
        outputs = self.read_outputs()
        if name is None:
            if not outputs:
                return 0
            return next(iter(outputs.values()))
        if name not in outputs:
            raise SimulationError(f"'{name}' is not an output port of this module")
        return outputs[name]

    # -- evaluation / stepping --------------------------------------------
    def evaluate(self, inputs: Optional[Dict[str, int]] = None) -> Dict[str, int]:
        """Settle the combinational logic and return the module outputs."""
        self.set_inputs(inputs)
        env = self.settle()
        return self.read_outputs(env)

    def step(self, inputs: Optional[Dict[str, int]] = None) -> CycleRecord:
        """Advance one clock cycle."""
        self.set_inputs(inputs)
        env = self.settle()
        before = self.register_values()
        outputs = self.read_outputs(env)

        # Phase 2: compute every next value before committing any of them.
        pending: List[Tuple[Operation, int]] = [
            (register, register.next_value(env)) for register in self._registers
        ]
        next_values = {
            self.register_name(register): value for register, value in pending
        }
        for register, value in pending:
            register.commit(value)

        record = CycleRecord(
            cycle=self.cycle,
            inputs=dict(self.inputs),
            outputs=outputs,
            registers=before,
            next_registers=next_values,
        )
        if self.record_trace:
            self.trace.append(record)
        self.cycle += 1
        return record

    def run(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        stimulus: Optional[Sequence[Dict[str, int]]] = None,
    ) -> SimulationTrace:
        """Run ``cycles`` clock cycles.

        ``inputs`` is held constant; ``stimulus`` (if given) supplies per-cycle
        input overrides.
        """
        self.set_inputs(inputs)
        for index in range(max(0, cycles)):
            override = None
            if stimulus is not None and index < len(stimulus):
                override = stimulus[index]
            self.step(override)
        return self.trace

    # -- convenience ------------------------------------------------------
    def output_after(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        name: Optional[str] = None,
    ) -> int:
        """Run ``cycles`` cycles and read an output from the settled state."""
        self.run(cycles, inputs)
        self.settle()
        return self.get_output(name)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        symbol = self.module.attributes.get("sym_name")
        label = symbol.value if symbol is not None else "?"
        return (
            f"<CircuitSimulator @{label} ports={len(self._ports)} "
            f"registers={len(self._registers)} cycle={self.cycle}>"
        )


def simulate_combinational(
    module: Operation, inputs: Dict[str, int], output: Optional[str] = None
) -> int:
    """One-shot helper: evaluate a purely combinational module."""
    simulator = CircuitSimulator(module)
    simulator.evaluate(inputs)
    return simulator.get_output(output)

