"""Attribute analysis: turning MLIR attributes into semantic values.

Rules cannot rewrite an :class:`~src.mlir.ir.Attribute`; they need the value
inside it.  This module performs that unwrapping once, up front, so the rule set
in :mod:`src.k_circt.semantics` only ever deals with Python integers, strings and
lists:

* ``IntegerAttr(42, i32)``      -> ``42``
* ``StringAttr("eq")``          -> ``"eq"``
* ``ArrayAttr([...])``          -> ``[...]`` (recursively resolved)
* ``TypeAttr((i32) -> i32)``    -> the :class:`~src.mlir.ir.Type` itself
* ``FlatSymbolRefAttr("@f")``   -> the *operation* ``@f`` names, looked up
  through :mod:`src.k_circt.symbols`

The last case is why this is an analysis rather than a one-line helper: resolving
a symbol-valued attribute needs the scope tree, so attribute resolution is
layered on top of symbol resolution exactly as it is in a K definition.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

from mlir.ir import (
    ArrayAttr,
    Attribute,
    BoolAttr,
    DictAttr,
    FlatSymbolRefAttr,
    FloatAttr,
    IntegerAttr,
    Operation,
    StringAttr,
    Trait,
    Type,
    TypeAttr,
    UnitAttr,
)

from .symbols import SymbolResolution, SymbolResolver

__all__ = [
    "ResolvedAttribute",
    "AttributeResolution",
    "AttributeResolver",
    "resolve_attributes",
]

#: Attributes that carry structural bookkeeping rather than semantic values.
STRUCTURAL_ATTRIBUTES = frozenset(
    {"port_names", "port_directions", "assembly_keywords", "operand_segment_sizes"}
)


@dataclass
class ResolvedAttribute:
    """One attribute, unwrapped."""

    op: Operation
    name: str
    attribute: Attribute
    value: Any
    type: Optional[Type] = None
    symbol_target: Optional[Operation] = None

    @property
    def owner_name(self) -> str:
        return self.op.name

    @property
    def is_symbol(self) -> bool:
        return isinstance(self.attribute, FlatSymbolRefAttr)

    @property
    def is_resolved(self) -> bool:
        if self.is_symbol:
            return self.symbol_target is not None
        return self.value is not None

    def __str__(self) -> str:
        suffix = f" : {self.type}" if self.type is not None else ""
        return f"{self.op.name}.{self.name} = {self.value!r}{suffix}"


@dataclass
class AttributeResolution:
    """The result of running :class:`AttributeResolver` over a whole tree."""

    bindings: List[ResolvedAttribute] = field(default_factory=list)
    errors: List[str] = field(default_factory=list)

    # -- counts -----------------------------------------------------------
    @property
    def num_resolved(self) -> int:
        return sum(1 for b in self.bindings if b.is_resolved)

    @property
    def num_attributes(self) -> int:
        return len(self.bindings)

    @property
    def unresolved(self) -> List[ResolvedAttribute]:
        return [b for b in self.bindings if not b.is_resolved]

    @property
    def is_complete(self) -> bool:
        return not self.unresolved and not self.errors

    # -- lookup -----------------------------------------------------------
    def for_operation(self, op: Operation) -> Dict[str, Any]:
        return {b.name: b.value for b in self.bindings if b.op is op}

    def named(self, name: str) -> List[ResolvedAttribute]:
        return [b for b in self.bindings if b.name == name]

    def values(self, name: str) -> List[Any]:
        return [b.value for b in self.named(name)]

    def first(self, name: str, default: Any = None) -> Any:
        found = self.named(name)
        return found[0].value if found else default

    def __len__(self) -> int:
        return len(self.bindings)

    def to_text(self) -> str:
        return "\n".join(str(b) for b in self.bindings)


class AttributeResolver:
    """Unwraps attributes into Python values, resolving symbol references."""

    def __init__(
        self,
        root: Optional[Operation] = None,
        symbols: Optional[SymbolResolution] = None,
    ) -> None:
        self.root = root
        if symbols is not None:
            self.symbols: Optional[SymbolResolution] = symbols
        elif root is not None:
            self.symbols = SymbolResolver(root).resolve()
        else:
            self.symbols = None
        self._resolution: Optional[AttributeResolution] = None

    # -- single attributes ------------------------------------------------
    def resolve(self, attr: Optional[Attribute]) -> Any:
        """Unwrap one attribute into a plain Python value."""
        if attr is None:
            return None
        if isinstance(attr, (IntegerAttr,)):
            return int(attr.value)
        if isinstance(attr, BoolAttr):
            return bool(attr.value)
        if isinstance(attr, FloatAttr):
            return float(attr.value)
        if isinstance(attr, StringAttr):
            return attr.value
        if isinstance(attr, TypeAttr):
            return attr.value
        if isinstance(attr, UnitAttr):
            return True
        if isinstance(attr, FlatSymbolRefAttr):
            return str(attr.value)
        if isinstance(attr, ArrayAttr):
            return [self.resolve(element) for element in attr.value]
        if isinstance(attr, DictAttr):
            return {key: self.resolve(item) for key, item in attr.value.items()}
        return attr.value

    def resolve_attribute(
        self, op: Operation, name: str, default: Any = None
    ) -> Any:
        """The resolved value of ``op``'s ``name`` attribute."""
        attr = op.attributes.get(name)
        if attr is None:
            return default
        return self.resolve(attr)

    def resolve_operation(self, op: Operation) -> Dict[str, Any]:
        """Every attribute of ``op``, resolved."""
        return {name: self.resolve(attr) for name, attr in op.attributes.items()}

    def resolve_symbol(self, attr: Optional[Attribute]) -> Optional[Operation]:
        """The operation a symbol-valued attribute refers to."""
        if attr is None or self.symbols is None:
            return None
        name = self.resolve(attr)
        if not isinstance(name, str):
            return None
        return self.symbols.operation(name)

    def attribute_type(self, attr: Optional[Attribute]) -> Optional[Type]:
        """The type annotation carried by a typed attribute, if any."""
        if attr is None:
            return None
        if isinstance(attr, TypeAttr):
            return attr.value
        return getattr(attr, "type", None)

    # -- constants ---------------------------------------------------------
    def constant_value(self, op: Operation) -> Optional[int]:
        """The integer a constant-like operation carries."""
        if not op.has_trait(Trait.CONSTANT_LIKE) and not op.name.endswith(".constant"):
            return None
        value = self.resolve_attribute(op, "value")
        return int(value) if isinstance(value, (int, float, bool)) else None

    def constants(self, scope: Optional[str] = None) -> List[Tuple[str, int]]:
        """Every ``(ssa name, value)`` constant pair, optionally within ``scope``."""
        found: List[Tuple[str, int]] = []
        for op in self._scope_operations(scope):
            value = self.constant_value(op)
            if value is None:
                continue
            name = op.result(0).name if op.num_results else ""
            found.append((name or "", value))
        return found

    def lookup_constant(self, name: str, scope: Optional[str] = None) -> Optional[int]:
        """The value of the constant bound to SSA name ``name``."""
        wanted = name.lstrip("%")
        for ssa_name, value in self.constants(scope):
            if ssa_name == wanted:
                return value
        return None

    def first_constant(self, scope: Optional[str] = None) -> Optional[int]:
        """The value of the first constant in textual order."""
        constants = self.constants(scope)
        return constants[0][1] if constants else None

    def _scope_operations(self, scope: Optional[str]) -> List[Operation]:
        """Operations under ``scope`` (a symbol name), or the whole tree."""
        root = self.root
        if scope is not None and self.symbols is not None:
            candidate = self.symbols.operation(scope)
            if candidate is not None:
                root = candidate
        if root is None:
            return []
        collected: List[Operation] = []
        root.walk(collected.append)
        return collected

    # -- whole-tree analysis ----------------------------------------------
    def resolve_all(self) -> AttributeResolution:
        """Resolve every attribute in the tree (cached)."""
        if self._resolution is not None:
            return self._resolution
        resolution = AttributeResolution()
        if self.root is None:
            self._resolution = resolution
            return resolution

        def visit(op: Operation) -> None:
            for name, attr in op.attributes.items():
                if name in STRUCTURAL_ATTRIBUTES:
                    continue
                binding = ResolvedAttribute(
                    op=op,
                    name=name,
                    attribute=attr,
                    value=self.resolve(attr),
                    type=self.attribute_type(attr),
                )
                if binding.is_symbol:
                    binding.symbol_target = self.resolve_symbol(attr)
                    if binding.symbol_target is None:
                        resolution.errors.append(
                            f"'{op.name}' refers to unknown symbol @{binding.value}"
                        )
                resolution.bindings.append(binding)

        self.root.walk(visit)
        self._resolution = resolution
        return resolution

    @property
    def resolution(self) -> AttributeResolution:
        return self.resolve_all()

    @property
    def num_resolved(self) -> int:
        return self.resolve_all().num_resolved

    def __len__(self) -> int:
        return len(self.resolve_all())

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        label = self.root.name if self.root is not None else "<none>"
        return f"<AttributeResolver root={label!r}>"


def resolve_attributes(
    root: Operation, symbols: Optional[SymbolResolution] = None
) -> AttributeResolution:
    """Convenience wrapper: ``resolve_attributes(module).num_resolved``."""
    return AttributeResolver(root, symbols).resolve_all()

"""Stateful circuit execution: register cells and the cycle driver.

:mod:`src.k_circt.semantics` says what each operation *means*; this module holds
the state those rules read and write, and sequences a clock cycle:

1. seed ``<inputs>``/``<env>`` from the port values,
2. drain ``<k>`` with the combinational rules (registers read as ``<state>``),
3. run the sequential rules so every register stages its next value in
   ``<next>``,
4. fire :class:`~src.k_circt.semantics.ClockEdgeRule` to commit ``<next>`` into
   ``<state>`` and advance ``<cycle>``.

Steps 2 and 3 are deliberately separate: a register never observes another
register's post-edge value, which is what makes the counter in
``inputs/counter.mlir`` increment by exactly one per cycle.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterator, List, Optional, Sequence

from mlir.ir import Block, Operation, Trait, Value

from .configuration import KConfiguration
from .semantics import (
    CIRCUIT_RULES,
    RuleApplication,
    RuleEngine,
    RulePhase,
    RuleSet,
    SemanticError,
    register_key,
)

__all__ = [
    "RegisterCell",
    "CircuitState",
    "CycleResult",
    "StatefulCircuit",
    "execute_function",
]

#: Operations that own a hardware module body.
MODULE_OPS = ("hw.module", "hw.module.extern", "firrtl.module", "sv.module")


# ---------------------------------------------------------------------------
# Register state
# ---------------------------------------------------------------------------


@dataclass
class RegisterCell:
    """One register's state, as it appears in the ``<state>`` cell."""

    name: str
    width: int = 0
    value: int = 0
    next_value: Optional[int] = None
    reset_value: int = 0
    op: Optional[Operation] = None
    cycles_latched: int = 0

    def mask(self) -> int:
        return (1 << self.width) - 1 if self.width > 0 else 0

    def truncate(self, value: int) -> int:
        mask = self.mask()
        return int(value) & mask if mask else int(value)

    # -- two-phase update -------------------------------------------------
    def read(self) -> int:
        return self.value

    def write(self, value: int) -> int:
        self.value = self.truncate(value)
        return self.value

    def stage(self, value: int) -> int:
        self.next_value = self.truncate(value)
        return self.next_value

    def commit(self) -> int:
        if self.next_value is not None:
            self.value = self.next_value
            self.next_value = None
            self.cycles_latched += 1
        return self.value

    def reset(self) -> int:
        self.value = self.truncate(self.reset_value)
        self.next_value = None
        self.cycles_latched = 0
        return self.value

    def __str__(self) -> str:
        return f"{self.name} |-> {self.value} (i{self.width})"


class CircuitState:
    """The register state of one circuit, keyed by register name."""

    def __init__(self, cells: Optional[Sequence[RegisterCell]] = None) -> None:
        self.cells: Dict[str, RegisterCell] = {}
        for cell in cells or ():
            self.cells[cell.name] = cell

    # -- construction -----------------------------------------------------
    @classmethod
    def from_module(
        cls, module: Operation, rules: Optional[RuleSet] = None
    ) -> "CircuitState":
        """Discover every register in ``module``'s body.

        A "register" is any operation the rule set gives a *sequential* rule, so
        adding a stateful operation to the semantics automatically teaches the
        executor about it.
        """
        rule_set = rules if rules is not None else CIRCUIT_RULES
        cells: List[RegisterCell] = []
        for op in _body_operations(module):
            if not rule_set.rules_for(op.name, RulePhase.SEQUENTIAL):
                continue
            cells.append(
                RegisterCell(
                    name=register_key(op),
                    width=_width_of_op(op),
                    reset_value=_reset_value_of(op),
                    op=op,
                )
            )
        state = cls(cells)
        state.reset()
        return state

    # -- access -----------------------------------------------------------
    def cell(self, name: str) -> Optional[RegisterCell]:
        return self.cells.get(name)

    def read(self, name: str, default: int = 0) -> int:
        cell = self.cells.get(name)
        return cell.value if cell is not None else int(default)

    def write(self, name: str, value: int) -> int:
        cell = self.cells.get(name)
        if cell is None:
            cell = self.cells.setdefault(name, RegisterCell(name=name))
        return cell.write(value)

    def stage(self, name: str, value: int) -> int:
        cell = self.cells.get(name)
        if cell is None:
            cell = self.cells.setdefault(name, RegisterCell(name=name))
        return cell.stage(value)

    def commit(self) -> Dict[str, int]:
        return {name: cell.commit() for name, cell in self.cells.items()}

    def reset(self) -> Dict[str, int]:
        return {name: cell.reset() for name, cell in self.cells.items()}

    # -- views -------------------------------------------------------------
    def snapshot(self) -> Dict[str, int]:
        return {name: cell.value for name, cell in self.cells.items()}

    def names(self) -> List[str]:
        return list(self.cells)

    @property
    def registers(self) -> List[RegisterCell]:
        return list(self.cells.values())

    @property
    def is_stateful(self) -> bool:
        return bool(self.cells)

    # -- configuration interop --------------------------------------------
    def load_into(self, config: KConfiguration) -> KConfiguration:
        """Copy this state into a configuration's ``<state>`` cell."""
        config.state.clear()
        config.state.update(self.snapshot())
        return config

    def sync_from(self, config: KConfiguration) -> "CircuitState":
        """Adopt the values a rule left in ``<state>``."""
        for name, value in config.state.items():
            self.write(name, value)
        return self

    def __len__(self) -> int:
        return len(self.cells)

    def __iter__(self) -> Iterator[RegisterCell]:
        return iter(self.cells.values())

    def __contains__(self, name: str) -> bool:
        return name in self.cells

    def __str__(self) -> str:
        return " ".join(str(cell) for cell in self.cells.values()) or ".Map"

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<CircuitState registers={list(self.cells)}>"


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _body_operations(module: Operation) -> List[Operation]:
    if not module.regions or not module.regions[0].blocks:
        return []
    return list(module.regions[0].blocks[0].operations)


def _width_of_op(op: Operation) -> int:
    from circt.hw_dialect import bit_width_of

    for result in op.results:
        width = bit_width_of(result.type)
        if width:
            return width
    return int(getattr(op, "_declared_width", 0) or 0)


def _reset_value_of(op: Operation) -> int:
    """The register's power-on value.

    ``seq.compreg %next, %clk reset %reset, %c0_i8`` names its reset value with
    an operand, so the constant behind that operand is read directly - the reset
    value has to be known before any rule has settled the design.  The operand
    index comes from the dialect class (``seq.compreg.ce`` puts a clock enable
    before the reset pair), defaulting to CIRCT's plain-register layout.
    """
    declared = int(getattr(op, "reset_value", 0) or 0)
    index = int(getattr(op, "RESET_VALUE", 3))
    operands = op.operands
    if len(operands) <= index:
        return declared
    operand = operands[index]
    if not isinstance(operand, Value):
        return declared
    defining = operand.defining_op
    if defining is None:
        return declared
    attr = defining.attributes.get("value")
    if attr is None or not defining.has_trait(Trait.CONSTANT_LIKE):
        return declared
    try:
        return int(attr.value)
    except (TypeError, ValueError):  # pragma: no cover - defensive
        return declared


# ---------------------------------------------------------------------------
# Cycle results
# ---------------------------------------------------------------------------


@dataclass
class CycleResult:
    """Everything one clock cycle produced."""

    cycle: int
    inputs: Dict[str, int] = field(default_factory=dict)
    outputs: Dict[str, int] = field(default_factory=dict)
    registers: Dict[str, int] = field(default_factory=dict)
    next_registers: Dict[str, int] = field(default_factory=dict)
    applications: List[RuleApplication] = field(default_factory=list)

    @property
    def num_steps(self) -> int:
        return len(self.applications)

    def rule_names(self) -> List[str]:
        return [application.rule for application in self.applications]

    def output(self, name: Optional[str] = None, default: int = 0) -> int:
        if name is None:
            return next(iter(self.outputs.values()), default)
        return self.outputs.get(name, default)

    def __str__(self) -> str:
        parts = [f"cycle={self.cycle}"]
        for label, values in (
            ("in", self.inputs),
            ("state", self.registers),
            ("out", self.outputs),
        ):
            if values:
                rendered = ", ".join(f"{k}={v}" for k, v in sorted(values.items()))
                parts.append(f"{label}({rendered})")
        parts.append(f"steps={self.num_steps}")
        return " ".join(parts)


# ---------------------------------------------------------------------------
# Executor
# ---------------------------------------------------------------------------


class StatefulCircuit:
    """Executes an ``hw.module`` through the semantic rules, cycle by cycle."""

    def __init__(
        self,
        module: Operation,
        rules: Optional[RuleSet] = None,
        engine: Optional[RuleEngine] = None,
    ) -> None:
        if module.name not in MODULE_OPS:
            raise SemanticError(
                f"expected a hardware module operation, got '{module.name}'"
            )
        self.module = module
        self.rules = rules if rules is not None else CIRCUIT_RULES
        self.engine = engine if engine is not None else RuleEngine(self.rules)
        self.config = KConfiguration.initial()
        self.state = CircuitState.from_module(module, self.rules)

        self._body: List[Operation] = _body_operations(module)
        self._ports = list(getattr(module, "ports", []) or [])
        self._input_ports = [p for p in self._ports if not p.is_output]
        self._output_ports = [p for p in self._ports if p.is_output]
        self._registers = [
            cell.op for cell in self.state.registers if cell.op is not None
        ]
        self.inputs: Dict[str, int] = {p.name: 0 for p in self._input_ports}
        self.reset()

    # -- structure --------------------------------------------------------
    @property
    def ports(self) -> List[Any]:
        return list(self._ports)

    @property
    def input_names(self) -> List[str]:
        return [p.name for p in self._input_ports]

    @property
    def output_names(self) -> List[str]:
        return [p.name for p in self._output_ports]

    @property
    def body(self) -> List[Operation]:
        return list(self._body)

    @property
    def registers(self) -> List[RegisterCell]:
        return self.state.registers

    @property
    def is_sequential(self) -> bool:
        return self.state.is_stateful

    @property
    def cycle(self) -> int:
        return self.config.cycle

    # -- lifecycle --------------------------------------------------------
    def reset(self) -> "StatefulCircuit":
        """Assert reset: clear the configuration and re-seed register state."""
        self.config.reset()
        self.state.reset()
        self.state.load_into(self.config)
        self.engine.reset()
        return self

    def set_input(self, name: str, value: int) -> None:
        if name not in self.inputs:
            raise SemanticError(f"'{name}' is not an input port of this module")
        self.inputs[name] = int(value)

    def set_inputs(self, values: Optional[Dict[str, int]]) -> None:
        for name, value in (values or {}).items():
            self.set_input(name, value)

    # -- phase 1: combinational settle ------------------------------------
    def settle(
        self, inputs: Optional[Dict[str, int]] = None
    ) -> List[RuleApplication]:
        """Bind the ports, then drain ``<k>`` with the combinational rules."""
        self.set_inputs(inputs)
        self._seed_environment()
        return self.engine.settle(self.config, self._body)

    def _seed_environment(self) -> None:
        config = self.config
        config.cell("env").clear()
        config.cell("outputs").clear()
        config.inputs.clear()
        config.inputs.update(self.inputs)
        self.state.load_into(config)

        block = self._entry_block()
        if block is None:
            return
        for index, argument in enumerate(block.arguments):
            name = (
                self._input_ports[index].name
                if index < len(self._input_ports)
                else (argument.name or f"arg{index}")
            )
            value = int(self.inputs.get(name, 0))
            config.bind(argument, value)
            if name:
                config.bind(name, value)

    def _entry_block(self) -> Optional[Block]:
        if not self.module.regions or not self.module.regions[0].blocks:
            return None
        return self.module.regions[0].blocks[0]

    # -- phase 2: clock edge ----------------------------------------------
    def step(self, inputs: Optional[Dict[str, int]] = None) -> CycleResult:
        """Advance one clock cycle and report what happened."""
        applications = list(self.settle(inputs))
        before = self.state.snapshot()
        outputs = dict(self.config.outputs)

        applications.extend(self.engine.latch(self.config, self._registers))
        staged = dict(self.config.next_state)
        cycle = self.config.cycle
        applications.append(self.engine.clock_edge(self.config))
        self.state.sync_from(self.config)

        return CycleResult(
            cycle=cycle,
            inputs=dict(self.inputs),
            outputs=outputs,
            registers=before,
            next_registers=staged,
            applications=applications,
        )

    def run(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        stimulus: Optional[Sequence[Dict[str, int]]] = None,
    ) -> List[CycleResult]:
        """Run ``cycles`` clock cycles, returning one result per cycle."""
        self.set_inputs(inputs)
        results: List[CycleResult] = []
        for index in range(max(0, cycles)):
            override = None
            if stimulus is not None and index < len(stimulus):
                override = stimulus[index]
            results.append(self.step(override))
        return results

    # -- reading results --------------------------------------------------
    def evaluate(self, inputs: Optional[Dict[str, int]] = None) -> Dict[str, int]:
        """Settle without a clock edge and return the module outputs."""
        self.settle(inputs)
        return dict(self.config.outputs)

    def output(self, name: Optional[str] = None, default: int = 0) -> int:
        outputs = self.config.outputs
        if name is None:
            return next(iter(outputs.values()), default)
        if name not in outputs:
            raise SemanticError(f"'{name}' is not an output port of this module")
        return outputs[name]

    def output_after(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        name: Optional[str] = None,
    ) -> int:
        """Run ``cycles`` cycles, settle once more, then read an output."""
        self.run(cycles, inputs)
        self.settle()
        return self.output(name)

    def register_values(self) -> Dict[str, int]:
        return self.state.snapshot()

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        symbol = self.module.attributes.get("sym_name")
        label = symbol.value if symbol is not None else "?"
        return (
            f"<StatefulCircuit @{label} ports={len(self._ports)} "
            f"registers={len(self.state)} cycle={self.cycle}>"
        )


# ---------------------------------------------------------------------------
# Functional (arith / func) execution
# ---------------------------------------------------------------------------


def execute_function(
    func: Operation,
    arguments: Optional[Sequence[int]] = None,
    rules: Optional[RuleSet] = None,
) -> Dict[str, int]:
    """Evaluate a single-block ``func.func`` body through the same rules.

    This is what connects the semantic layer back to the MLIR sample input: the
    ``arith`` rules in :mod:`src.k_circt.semantics` evaluate ``@fold_chain``
    without the circuit machinery being involved at all.
    """
    if func.name not in ("func.func", "builtin.func"):
        raise SemanticError(f"expected a function operation, got '{func.name}'")
    if not func.regions or not func.regions[0].blocks:
        return {}

    engine = RuleEngine(rules if rules is not None else CIRCUIT_RULES)
    config = KConfiguration.initial()
    block = func.regions[0].blocks[0]

    supplied = list(arguments or ())
    for index, argument in enumerate(block.arguments):
        value = supplied[index] if index < len(supplied) else 0
        config.bind(argument, int(value))
        if argument.name:
            config.bind(argument.name, int(value))

    config.enqueue_all(list(block.operations))
    engine.run(config, RulePhase.FUNCTIONAL)
    return dict(config.outputs)

