class SemanticRule:
    """One explicit rewrite rule.

    Subclasses override :meth:`compute` (the interesting part) and inherit the
    plumbing: reading operands out of ``<env>``, truncating to the result width
    and binding the result back into ``<env>``.
    """

    #: Short kebab-case identifier used in traces.
    NAME: str = "rule"
    #: Operations this rule applies to.  Empty means "config-level rule".
    OP_NAMES: Tuple[str, ...] = ()
    #: When the rule may fire.
    PHASE: RulePhase = RulePhase.COMBINATIONAL
    #: Higher priority rules are tried first for the same operation.
    PRIORITY: int = 0
    #: The K rule this implements, for documentation and ``describe()``.
    K_RULE: str = ""

    # -- matching ---------------------------------------------------------
    def matches(self, op: Optional[Operation], config: KConfiguration) -> bool:
        if op is None:
            return not self.OP_NAMES
        return op.name in self.OP_NAMES and self.side_condition(op, config)

    def side_condition(self, op: Operation, config: KConfiguration) -> bool:
        """Extra guard, spelled ``requires`` in a K rule."""
        return True

    # -- operand access ---------------------------------------------------
    def read(
        self,
        op: Operation,
        config: KConfiguration,
        index: int,
        default: Optional[int] = None,
    ) -> int:
        """Read operand ``index`` from ``<env>``, or get stuck."""
        operands = op.operands
        if index >= len(operands):
            if default is None:
                raise StuckError(f"'{op.name}' has no operand {index}")
            return int(default)
        value = config.lookup(operands[index])
        if value is None:
            if default is not None:
                return int(default)
            raise StuckError(f"operand {index} of '{op.name}' is unbound")
        return int(value)

    def read_all(self, op: Operation, config: KConfiguration) -> List[int]:
        return [self.read(op, config, index) for index in range(len(op.operands))]

    # -- result handling --------------------------------------------------
    def width(self, op: Operation) -> int:
        return _result_width(op)

    def truncate(self, op: Operation, value: int) -> int:
        width = self.width(op)
        return int(value) & ((1 << width) - 1) if width > 0 else int(value)

    def bind(self, op: Operation, config: KConfiguration, value: int) -> int:
        """Bind ``value`` to every result of ``op`` (and to its SSA name)."""
        for result in op.results:
            config.bind(result, value)
            if result.name:
                config.bind(result.name, value)
        return value

    def label(self, op: Operation) -> str:
        names = [f"%{r.name}" for r in op.results if r.name]
        return ", ".join(names)

    # -- application ------------------------------------------------------
    def compute(self, op: Operation, config: KConfiguration) -> int:
        """The rule's arithmetic.  Overridden by every concrete rule."""
        raise NotImplementedError(f"{self.NAME} does not implement compute()")

    def apply(
        self, op: Optional[Operation], config: KConfiguration
    ) -> RuleApplication:
        """Fire the rule, rewriting ``config``, and return the trace record."""
        assert op is not None, f"{self.NAME} needs an operation"
        operands = tuple(self.read_all(op, config))
        value = self.truncate(op, self.compute(op, config))
        self.bind(op, config, value)
        return RuleApplication(
            rule=self.NAME,
            op_name=op.name,
            label=self.label(op),
            operands=operands,
            result=value,
            cycle=config.cycle,
            phase=self.PHASE,
        )

    # -- reporting --------------------------------------------------------
    def describe(self) -> str:
        rule = self.K_RULE.strip() or f"rule {self.NAME}"
        targets = ", ".join(self.OP_NAMES) or "<configuration>"
        return f"{self.NAME} [{self.PHASE.value}] on {targets}\n    {rule}"

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<{type(self).__name__} {self.NAME!r}>"


class ConfigurationRule(SemanticRule):
    """A rule that rewrites cells directly rather than evaluating an operation."""

    OP_NAMES: Tuple[str, ...] = ()

    def apply(
        self, op: Optional[Operation], config: KConfiguration
    ) -> RuleApplication:
        raise NotImplementedError

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        """A register reads as its *current* state, not its input."""
        return self.truncate(self.current_value)

    def fold(self) -> Optional[List[Any]]:
        return None


class CompRegOp(SeqOp):
    """``seq.compreg %next, %clk reset %reset, %resetValue : i8``.

    Operand order follows CIRCT: ``(input, clock[, reset, resetValue])``.
    """

    OPERATION_NAME = "seq.compreg"

    #: Operand indices.
    INPUT = 0
    CLOCK = 1
    RESET = 2
    RESET_VALUE = 3

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 0,
        input_signal: Optional[Union[Value, str]] = None,
        clock: Union[Value, str] = "clk",
        reset: Optional[Union[Value, str]] = None,
        reset_value: int = 0,
        reset_type: ResetType = ResetType.SYNC,
        current_value: int = 0,
        clock_domain: Optional[ClockDomain] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if input_signal is not None:
                ops.append(input_signal)
            ops.append(clock)
            if reset is not None:
                ops.append(reset)
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("name", StringAttr(name))
        super().__init__(
            operands=ops,
            result_types=result_types,
            attributes=attrs,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.reg_name = name or ""
        self.reset_value = int(reset_value)
        self.reset_type = reset_type
        self.current_value = int(current_value)
        self.clock_domain = clock_domain
        self.cycles_ticked = 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        name_attr = kwargs.get("attributes", {}).get("name")
        op.reg_name = name_attr.value if name_attr is not None else op.result_name
        op.reset_type = ResetType.SYNC
        op.reset_value = 0
        op.current_value = 0
        op.clock_domain = None
        op.cycles_ticked = 0
        return op

    # -- operand accessors -------------------------------------------------
    @property
    def has_reset(self) -> bool:
        return self.num_operands > self.RESET

    @property
    def input_signal(self) -> Any:
        return self.get_operand(self.INPUT) if self.num_operands > self.INPUT else None

    @property
    def clock(self) -> Any:
        return self.get_operand(self.CLOCK) if self.num_operands > self.CLOCK else None

    @property
    def reset(self) -> Any:
        return self.get_operand(self.RESET) if self.has_reset else None

    def declared_reset_value(self, env: SignalEnv) -> int:
        """The reset value, read from the operand when the IR supplies one."""
        if self.num_operands > self.RESET_VALUE:
            return self.read_operand(env, self.RESET_VALUE)
        return self.reset_value

    def reset_active(self, env: SignalEnv) -> bool:
        if not self.has_reset:
            return False
        if self.reset_type is ResetType.NONE:
            return False
        return bool(self.read_operand(env, self.RESET) & 1)

    def async_reset(self, env: Optional[SignalEnv] = None) -> bool:
        env = env or {}
        return self.reset_type is ResetType.ASYNC and self.reset_active(env)

    # -- clocked behaviour -------------------------------------------------
    def next_value(self, env: SignalEnv) -> int:
        if self.reset_active(env):
            return self.truncate(self.declared_reset_value(env))
        return self.truncate(self.read_operand(env, self.INPUT))

    def reset_state(self, env: Optional[SignalEnv] = None) -> None:
        self.current_value = self.truncate(self.declared_reset_value(env or {}))
        self.cycles_ticked = 0

    def verify_op(self) -> List[str]:
        if self.num_operands < 2:
            return ["'seq.compreg' expects at least an input and a clock operand"]
        return []


class CompRegClockEnabledOp(CompRegOp):
    """``seq.compreg.ce`` - a register with an explicit clock enable."""

    OPERATION_NAME = "seq.compreg.ce"

    #: Operand indices (clock enable sits after the clock).

circt power-on regs: {'reg': 0}  evaluate: {'o': 0}
