class ReplicateOp(CombOp):
    """``comb.replicate %x : (i1) -> i4``."""

    OPERATION_NAME = "comb.replicate"

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        input_width: int = 0,
        count: int = 1,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(
            operands=operands,
            result_types=result_types,
            width=width,
            result_name=result_name,
            location=location,
        )
        self.input_width = int(input_width)
        self.count = int(count)

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.input_width = 0
        op.count = 1
        return op

    def _input_width(self) -> int:
        if self.input_width:
            return self.input_width
        for value in self.ssa_operands:
            width = bit_width_of(value.type)
            if width:
                return width
        return 1

    def _count(self) -> int:
        if self.num_results:
            source = self._input_width()
            if source:
                return max(1, self.width // source)
        return max(1, self.count)

    def infer_width(self, type_env: Optional[Dict[str, int]] = None) -> int:
        return self._input_width() * self._count()

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        source_width = self._input_width()
        source = self.read_operand(env or {}, 0) & ((1 << source_width) - 1)
        packed = 0
        for _ in range(self._count()):
            packed = (packed << source_width) | source
        total = self.width or (source_width * self._count())
        return packed & ((1 << total) - 1) if total else packed


class ParityOp(CombOp):
    """``comb.parity %x : (i8) -> i1`` - XOR reduction."""

    OPERATION_NAME = "comb.parity"

    @classmethod
    def result_types_from_trailing(
        cls, trailing_types: Sequence[Type], num_results: int
    ) -> List[Type]:
        return [IntegerType(1)] * num_results

    def infer_width(self, type_env: Optional[Dict[str, int]] = None) -> int:
        return 1

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        value = self.read_operand(env or {}, 0)
        parity = 0
        while value:
            parity ^= value & 1
            value >>= 1
        return parity


#: Every ``comb`` operation, keyed by its op name.
COMB_OPS: Dict[str, type] = {}
for _cls in (
    AddOp,
    SubOp,
    MulOp,
    DivUOp,
    DivSOp,
    ModUOp,
    ModSOp,
    AndOp,
    OrOp,
    XorOp,
    ShlOp,
    ShrUOp,
    ShrSOp,
    MuxOp,
    ICmpOp,
    ConcatOp,
    ExtractOp,
    ReplicateOp,
    ParityOp,
):
    COMB_DIALECT.register_operation(_cls)
    COMB_OPS[_cls.OPERATION_NAME] = _cls

